/* 针对各门YOLO课的案例补充；在课程组合完成后加载。 */
(()=>{
  const examples={
    'detection-intro':['从一张图片开始决定答案','一张路口图中有两辆车：分类回答“图中有车”，但无法告诉我们每辆车的位置。检测要为每辆车分别给出类别和框；如果没找到目标，结果可以为空。','例如框A左上角(10,20)、右下角(110,70)，它的宽为110−10=100、高为70−20=50。第二辆车需要另一条记录，不能把整张图的分类分数当作两辆车各自的答案。','框画在哪里取决于标注规则：车辆被遮挡时是否只框可见部分，需要在数据集中保持一致。规则不一致会让外观相似的图片收到互相冲突的监督。'],
    'detection-two-stage':['候选区域怎样进入第二阶段','设共享特征图上有100个候选区域。区域建议网络先提出位置，再由区域检测头读取每个候选对应的特征，预测类别并修正位置。第一阶段主要回答“哪里值得检查”，第二阶段继续判断“是什么、框怎样调整”。','例如候选在特征图中覆盖8×6个位置，检测头需要固定尺寸输入时，可将区域划成2×2格并分别汇总；每个通道得到2×2结果。候选之间大小可以不同，但输出格数相同。','Fast R-CNN共享整图特征，Faster R-CNN进一步以网络提出候选；区域提议与区域检测的分工，是理解“两阶段”的关键。'],
    'detection-one-stage':['直接预测仍有后处理','一阶段检测从共享特征的许多位置直接输出框和类别相关的数值，不先为每个候选单独运行区域检测头。不同尺度的特征可以一起参与预测，以覆盖不同的空间分辨率。','例如某位置产生三个候选，其中两个都指向同一辆车。模型前向产生候选后，仍可以按分数筛选，再根据候选框之间的重叠关系去重；NMS是整理预测，不是区域检测第二阶段。','一阶段或两阶段描述预测过程的组织；是否使用Anchor描述候选框的参数化方式，两个问题应分别判断。'],
    'yolo-evolution':['先确定代码版本，再读结构图','同叫YOLO的实现可能采用不同入口、特征融合方式和预测头。读结构图时，先记录仓库、版本、模型配置、类别数和输入尺寸，这些条件确定后才能核对层号与张量形状。','本课程采用YOLOv5 v7.0风格的Anchor检测头：640输入通常对应80、40、20三个网格。每格三个Anchor时，三个尺度的候选总数是3×(80²+40²+20²)=25,200。','若看到旧版Focus入口，不能只凭图中名字判断本课层号；先找到实际模型配置和解析代码，再比较它们如何改变输入和输出。'],
    'architecture':['一张图走过三个部分','一张640×640 RGB图整理成[1,3,640,640]后进入Backbone，逐层计算得到不同尺度的特征；Neck融合特征，Detect把每个位置的特征写成候选框参数和分数。','以两类、每格三个Anchor为例，每条候选有4个框参数、1个物体性和2个类别数，共7个数。P3输出[1,3,80,80,7]，P4、P5分别为[1,3,40,40,7]和[1,3,20,20,7]。','训练时标签参与目标分配和损失，优化器根据梯度更新参数；推理时解码、筛选、去重并还原坐标。两个过程都需要前向计算，但用途和后续步骤不同。'],
    'yolo-repository':['从一个问题找到要读的文件','当你想知道“为什么输入640后有三个尺度”，先看模型配置中每层的来源和模块，再看模型解析与前向如何连接各层。遇到具体模块的计算，再读该模块定义。','例如要查烟雾类别编号：数据配置中的names给出类别顺序，图片对应的标签文件第一列记录编号。查看模型配置可以理解输出结构，但无法证明标签中的0确实标的是烟雾。','排查训练损失时，从训练入口找到损失调用，再追踪目标分配与各项损失；排查推理框消失时，从检测入口追到阈值、NMS和坐标还原。'],
    'yolo-data':['从图片到一行可检查的标签','以宽1000、高500的图片为例，火焰框左上(400,160)、右下(600,240)。先算中心(500,200)与宽高(200,80)，再分别除以图宽和高，得到(0.5,0.4,0.2,0.16)。','若类别1表示火焰，标签行就是1 0.5 0.4 0.2 0.16。读取时要让同名图片和标签一一对应，并检查类别编号、坐标范围和框是否真正覆盖目标。','为了检查划分质量，应按视频、地点或其他来源分组；同一视频的相邻帧过于相似，跨训练集与验证集会让验证结果偏乐观。'],
    'yolo-config':['一行配置怎样变成一层模块','模型配置中的[from, number, module, args]分别给出输入来源、基础重复次数、模块名称和参数。from为−1通常取上一层；多输入来源会组成列表供拼接等模块使用。','例如上一层是[1,128,40,40]，若另一来源是[1,256,40,40]，沿通道拼接后为[1,384,40,40]。若高宽不同，应先查来源层或上采样，而不是把数据强行重排。','宽度、深度系数由解析器应用；C3的重复通常体现在内部Bottleneck数。核对一层时同时记录来源、模块参数和实际输出形状。'],
    'yolo-backbone':['从输入分辨率追踪到P3','对于640×640输入，连续三次按2倍降低空间尺寸，得到320、160、80；第五次降低后为20。每次改变高宽的是相应步幅卷积，C3本身在本配置中保持该尺度的高宽。','卷积核跨全部输入通道计算一张输出特征图：如果输入是3通道，使用64组卷积核，便得到64个输出通道。这64个数值通道是可学习特征，不对应64种预设类别。','卷积后BN调整各通道的数值，再由SiLU逐数引入非线性。它们在本块中保持形状；了解这点才能把尺寸变化与数值变化分开追踪。'],
    'yolo-c3':['把C3的两条路分别算出来','输入[1,8,4,4]经过两条独立的1×1卷积，各得到[1,4,4,4]。主路继续经过Bottleneck，另一路保留自己的投影结果；两路分别读取全部8个输入通道。','沿通道拼接时4+4=8，得到[1,8,4,4]，末端卷积再混合两路信息。拼接把数值并排放在不同通道；Bottleneck内部的残差相加则对对应位置逐个相加。','只有捷径开启、输入和输出形状相容时才能直接相加。例如对应位置输入3、变换结果0.2，相加得到3.2；拼接不会把这两个数变成3.2。'],
    'yolo-sppf':['三次池化为什么扩大观察范围','SPPF先用卷积调整通道，再对同一份特征连续做三次5×5、步幅1的最大池化。每次池化的一个输出取其窗口里的最大值，填充使高宽保持不变。','第一次输出可能受原特征上5×5位置影响；第二次的窗口汇合相邻第一次输出，范围扩大到9×9；第三次扩大到13×13。这里的范围以SPPF输入特征为参照。','将原特征和三次池化结果沿通道拼接后，卷积学习如何组合四路信息。若每路512通道，拼接后为2048通道，再可投影到1024通道。'],
    'yolo-neck':['两条尺度路径为什么都要看','深层20×20特征经过上采样与40×40特征拼接，再向80×80传播；之后融合后的较细特征又经下采样回到较粗尺度。这些连接让不同分辨率的信息在预测前相互组合。','例如[1,512,40,40]与[1,512,40,40]沿通道拼接，得到[1,1024,40,40]。通道可以不同，但批次、高和宽需要一致；随后C3学习如何融合拼接后的信息。','前向路径的信息汇合不叫反向传播。反向传播发生在训练求梯度时，沿计算图将损失对参数的影响传回。'],
    'yolo-head':['从特征数到可筛选的候选','检测头为每个位置和Anchor输出一组数。两类任务每组有7项：4个框参数、1个物体性、2个类别原始数；3组因此需要21个输出通道。','以P3的[1,21,80,80]为例，先按Anchor和字段分组为[1,3,7,80,80]，再交换轴得到[1,3,80,80,7]。指定图片、Anchor、行和列，就能取出一条候选的完整7项。','训练使用原始预测与分配后的标签计算损失；推理将框参数解码，组合物体性和类别分数，再筛选与去重。候选总数由网格与Anchor数量决定。'],
    'anchors':['参考宽高、标签框和预测框','真实框是标注答案；Anchor提供参考宽高；预测框由网络输出与参考一起解码得到。三者在同一位置出现，但各自承担不同作用。','以参考宽20为例，原始宽度参数为0时Sigmoid为0.5，解码宽度为(2×0.5)²×20=20；若Sigmoid为0.75，宽度为(1.5)²×20=45。真实框不需要恰好等于参考宽高。','训练分配还要比较标签宽高与参考宽高的比例；AutoAnchor检查的是数据标签与参考尺寸的适配情况，并没有运行模型或计算验证召回率。'],
    'yolo-assignment':['一条标签怎样找到负责位置','目标分配是在训练中决定哪些候选位置与某个真实目标配对。标签中心(0.53,0.47)、宽高(0.05,0.025)落到80×80网格后，中心是(42.4,37.6)，宽高是(4,2)。','中心落在第42列、第37行，局部中心为(0.4,0.6)。若一个Anchor通过宽高比例筛选，该位置可读取对应原始预测，与目标框和类别比较。其他尺度和Anchor需要分别判断。','目标靠近格子边界时，规则还可能分配水平或垂直邻格。例如左邻列41看同一中心为(1.4,0.6)；局部坐标不同，是因为参照格子改变。'],
    'yolo-loss':['把三种误差分开看','框损失衡量预测框与真实框的位置差异；物体性损失训练候选对目标的响应；类别损失训练类别字段。三项计算的位置和数量不完全一样，需要分别读。','例如正样本类别为火焰，类别目标[0,1]，预测分数[0.8,0.2]。两项BCE都约为1.609，平均仍约1.609，反映两个类别分数都偏离目标。','框重叠可以用IoU描述，CIoU还考虑中心距离和宽高比。各项按实现归约并乘权重后组合，日志分项和反传使用的总标量需要分别核对。'],
    'train-yolo':['一批数据如何改变参数','训练批次包含图片和标签。图片先经过模型得到三尺度原始预测，标签经分配规则找到负责位置，损失把这些预测与目标联系起来。','反向传播计算损失对参数的梯度；优化器在满足更新条件时调整参数，然后下一批数据使用更新后的模型。使用梯度累积时，多个批次可能共享一次参数更新。','一个epoch表示按数据加载规则遍历一轮训练集，不等于只更新一次。每轮之后用验证集检查模型，保存权重时也记录本次配置与数据版本。'],
    'yolo-checkpoints':['初始化与续训回答不同问题','新任务初始化是用已有参数作为起点，随后按照新数据重新训练；续训是从中断位置接着原实验，还需要优化器、训练进度等状态。','例如原头有80类、新任务有2类，输出卷积形状改变，不能直接把旧头张量装入新头；名称与形状匹配的其他参数可以按实现筛选加载。','即使类别数相同，也要检查类别顺序：原来0代表猫、新数据0代表狗时，单靠张量形状看不出语义已经改变。'],
    'yolo-augment':['增强同时作用于图片和标签','数据增强生成不同的训练输入，目的是让模型见到合理变化。例如水平翻转宽640的画面，原框左右坐标为100和200，翻转后左右为640−200=440和640−100=540。','几何变换必须同步改变框；颜色调整通常不移动框，但仍需要保证改变后的图像和标签有意义。Mosaic把多张图组合时，还要处理裁切和超出画面的框。','比较增强方案时固定数据划分和评价方法，记录训练预算、随机种子及配置。先看转换后的样本图，再比较验证指标。'],
    'yolo-evaluation':['从匹配结果到模型选择','验证先产生预测，再按类别、分数和IoU规则与真实框匹配。TP表示正确匹配的预测，FP表示未匹配预测，FN表示未匹配真实目标。','假设真实火焰有10处，模型正确找到8处、另有2处误报，则P=8/(8+2)=0.8，R=8/10=0.8。改变筛选门槛会改变保留的预测，也可能改变这两个数。','AP在固定类别和IoU条件下汇总不同门槛的精确率与召回率；mAP按评估协议进一步汇总。选择权重时还应逐类看漏检、误报及其场景。'],
    'inference':['从输入画布回到原图片','推理先按模型要求整理图像，模型输出候选后，再进行解码、分数筛选与NMS，最后将框恢复到原图坐标。结果中的坐标要说明属于哪个画布。','例如原图缩小为一半、左侧补20像素，输入画布中的角点(76,85,92,115)先让x减20，再让x和y都除以0.5，得到原图角点(112,170,144,230)。','置信度门槛决定哪些候选进入下一步；NMS的IoU门槛控制候选间去重；评价IoU门槛用于预测与标签的匹配。三者用途不同。'],
    'yolo-export':['模型文件与输入输出约定一起交付','导出模型是把计算图交给另一种运行环境。接收方还需要知道图像颜色顺序、尺寸、缩放和补边、数值范围、类别顺序、输出格式以及后处理规则。','对比两个运行环境时，先保存同一张已经预处理的输入张量，对齐原始输出，再对齐解码、筛选、NMS和坐标。若最终框不同，就能定位差异最早出现的环节。','例如一条候选在两端分别得0.7201和0.7199，门槛是0.72时前者通过、后者被筛掉。很小的数值差也可能变成最终框数量的差异。'],
    'yolo-trace':['同一图片的训练与推理分叉','图片先经过缩放补边和张量整理，再经过Backbone、Neck和Detect。两条路线共享这些前向步骤：训练接标签和损失，推理接解码与后处理。','输入640×480时，三个网格为80×60、40×30、20×15，每格三组参考，候选为3×(4800+1200+300)=18,900。改成640×640后候选为25,200；类别数改变每条字段数，不直接改变网格数。','跟踪时记录原图宽高、实际画布、缩放和补边、类别表、每层形状以及最终坐标系。每个数字都有明确来源，才能复现计算。'],
    'debugging':['先找出问题出现在哪一步','如果最终没有框，依次记录原始输出是否有限、分数筛选前后保留多少、NMS后剩多少，以及绘制前坐标是否落在原图内。最早出现异常的步骤给出下一步检查方向。','例如原始候选25,200个、分数筛选后240个、NMS后2个，但画面没有框，先检查坐标还原、裁边、类别过滤和绘制；此时已有证据表明模型并非没有产生候选。','如果训练损失出现NaN，记录首次发生的批次，检查输入、标签、模型输出和各损失项；固定复现样本后一次只改一项，比较修改前后的结果。']
  };
  const catalog=typeof lessons!=='undefined'?lessons:window.lessons;
  const rcnn=catalog.find(item=>item.id==='detection-two-stage');
  const detail=rcnn.sections[1];
  const detailStart=detail.paragraphs.length;
  detail.paragraphs.push(
    'R-CNN 的全称是 Regions with CNN features，即使用卷积神经网络特征处理候选区域。它把目标检测拆成候选区域生成、区域特征提取、类别打分和边界框修正。原论文使用 Selective Search（选择性搜索）提出约 2000 个候选区域，再逐个送入卷积网络。',
    '第一步：输入一张图片，Selective Search 根据颜色、纹理等相似性合并区域，产生不同大小和长宽比的候选框。这些框只是可能包含物体的区域；它们此时没有由 CNN 给出的类别。候选框覆盖不准会影响后续检测，因为后面的分类器只检查已经提出的区域。',
    '第二步：逐个从原图裁取候选区域，并将区域变换到 CNN 需要的固定尺寸。原论文的 AlexNet 型网络使用 227×227 输入；为保持上下文，论文在裁剪前还考虑候选区域周边的像素。不同宽高比的区域变换到固定尺寸时可能发生形变。',
    '第三步：每个 227×227 区域独立经过五个卷积层和全连接层，提取 4096 维的 fc7 特征。这个 4096 维向量是一组由网络计算出的数字，用来描述候选区域；它不是 4096 个类别。约 2000 个区域要分别经过 CNN，重叠区域中的图像内容也会重复计算。',
    '第四步：针对每个类别分别使用线性 SVM（支持向量机）给 fc7 特征打分。例如汽车 SVM 给某区域较高分，说明该区域的特征与训练出的汽车判别规则较吻合。不同类别分别打分，再结合阈值和非极大值抑制（NMS）整理重复检测。',
    '第五步：边界框回归器根据区域特征预测位置修正量，调整候选框的中心和宽高，使它更贴近目标。举例来说，原候选偏向汽车左侧，回归器可以将中心向右移动并调整宽度；修正量是学习得到的，具体结果取决于特征和参数。',
    '训练分为多个环节：先用图像分类数据预训练 CNN，再用带检测标注的候选区域微调；然后为类别训练线性 SVM，并训练边界框回归器。原始 R-CNN 并非一个同时端到端训练所有环节的单一检测网络。Fast R-CNN 的重要变化是整图共享卷积特征、再提取区域特征；Faster R-CNN 进一步使用区域建议网络产生候选。'
  );
  detail.subheadings={...(detail.subheadings||{}),[detailStart]:'R-CNN 原始流程：一张图如何得到检测结果'};
  detail.rcnnDiagram=detailStart;
  const fast=rcnn.sections[2], fastStart=fast.paragraphs.length;
  fast.paragraphs.push(
    'Fast R-CNN 要解决的问题是：R-CNN 对相互重叠的候选区域重复运行 CNN，导致同一片图像被计算多次。Fast R-CNN 先把整张图送入卷积网络，得到一张共享特征图；外部方法提出的候选框仍在原图坐标中，再映射到特征图上。',
    '以一个简单的映射为例：假设特征图相对于输入的总步幅为16，输入图上的候选框 (32,48,160,144) 大致对应特征图上的 (2,3,10,9)。实际实现还要处理边界、量化和取整；这里先用整除的例子看清坐标对应关系。',
    '候选框大小不同，全连接层却需要固定长度的输入。RoI Pooling 将映射后的区域划分为固定行列，每个小格分别取最大值。例如某通道对应 4×4 数表，划分成 2×2 格，每格包含 2×2 个数，若四格最大值分别为 6、8、14、16，则输出为 [[6,8],[14,16]]。各通道分别操作，得到固定高宽的区域特征。',
    '区域特征接入全连接层后分成两支：一支经 Softmax 输出类别与背景的分数，另一支输出边界框修正量。训练时分类损失与正样本框回归损失共同参与优化，整图卷积特征、区域特征和两支预测可以联合训练。Fast R-CNN 的候选区域通常仍由网络之外的方法产生。',
    'Faster R-CNN 把候选生成也接入网络：区域建议网络 RPN 在共享特征图上滑动，对每个位置的多组 Anchor 同时预测目标性分数和框偏移。Anchor 是参考框；RPN 解码偏移、筛选分数并进行 NMS 后，得到一批建议区域，交给后续区域检测头。',
    '例如一处位置设3组参考框，RPN 为每组输出一组目标性分类结果和4个框偏移。整张特征图上的候选汇合后先做筛选，后续检测头再判断具体类别并细调框。RPN 的目标性回答区域是否可能包含目标，最终分类头才区分汽车、行人等类别。',
    '三代方法的计算顺序因此很清楚：R-CNN 对每个候选独立提特征；Fast R-CNN 共享整图特征但仍使用外部候选；Faster R-CNN 让 RPN 与区域检测头共享特征。共享减少了重复卷积，实际耗时还受网络、候选数和硬件影响。'
  );
  fast.subheadings={...(fast.subheadings||{}),[fastStart]:'共享特征之后，候选框怎样继续走'};fast.fastDiagram=fastStart;
  rcnn.sources=rcnn.sources||[];rcnn.sources.push({label:'R-CNN 原论文：候选区域与 CNN 特征',url:'https://arxiv.org/abs/1311.2524'});
  for(const [id,paragraphs] of Object.entries(examples)){
    const lesson=catalog.find(item=>item.id===id);if(!lesson)throw Error('YOLO lesson missing: '+id);
    const [title,...text]=paragraphs;
    const section=lesson.sections[lesson.sections.length-1];
    const start=section.paragraphs.length;
    section.paragraphs.push(...text);
    section.subheadings={...(section.subheadings||{}),[start]:title};
    section.readerDiagram={start,paragraphs:text};
  }
  const old=window.visionlabYoloLearning.renderParagraph.bind(window.visionlabYoloLearning);
  const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  window.visionlabYoloLearning.renderParagraph=(section,index)=>{
    const existing=old(section,index);
    if(section.fastDiagram===index)return existing+'<figure class="yd-workshop yl-figure"><figcaption><strong>从共享特征到区域检测</strong></figcaption><ol class="yl-flow"><li><span>输入</span><b>整张图片 → 卷积网络 → 共享特征图</b></li><li><span>候选</span><b>Fast：外部候选；Faster：RPN 与 Anchor 产生建议</b></li><li><span>区域特征</span><b>候选映射到特征图 → RoI Pooling → 固定尺寸</b></li><li><span>两支输出</span><b>类别与背景分数 + 边界框修正</b></li></ol></figure>';
    if(section.rcnnDiagram===index)return existing+'<figure class="yd-workshop yl-figure"><figcaption><strong>R-CNN：候选区域逐个通过网络</strong></figcaption><ol class="yl-flow"><li><span>原图</span><b>Selective Search → 约 2000 个候选框</b></li><li><span>逐个处理</span><b>裁剪并变换 → 227 × 227 区域</b></li><li><span>特征提取</span><b>AlexNet 型 CNN → fc7 的 4096 维特征</b></li><li><span>分类与定位</span><b>类别 SVM 打分 + 边界框回归</b></li><li><span>结果整理</span><b>按类别筛选并用 NMS 去重</b></li></ol></figure>';
    if(!section.readerDiagram||index!==section.readerDiagram.start)return existing;
    const steps=section.readerDiagram.paragraphs.map((p,i)=>`<li><span>第 ${i+1} 步</span><b>${escape(p.split("。")[0])}</b></li>`).join('');
    return existing+`<figure class="yd-workshop yl-figure"><figcaption><strong>跟着例子走一遍</strong></figcaption><ol class="yl-flow">${steps}</ol></figure>`;
  };
})();
